import math
last=0.0
def interp(points,x):
 points=sorted(points)
 for a,b in zip(points,points[1:]):
  if a[0]<=x<=b[0]:
   f=(x-a[0])/max(.001,b[0]-a[0])
   return a[1]+f*(b[1]-a[1])
 return min(points,key=lambda p:abs(p[0]-x))[1]
def control(o):
 global last
 cam=o.get('views',{}).get('camera')
 h=o['hitch_deg']
 if not cam:return (last,-.35,-23)
 pts=[]
 for b,d in cam['walls']:
  a=math.radians(b+h)
  pts.append((-d*math.cos(a),d*math.sin(a)))
 if len(pts)<6:return (h*1.5,-.35,-23)
 cuts=[(math.hypot(pts[i][0]-pts[i-1][0],pts[i][1]-pts[i-1][1]),i) for i in range(1,len(pts))]
 cut=max(cuts)[1]
 sides=[pts[:cut],pts[cut:]]
 if min(map(len,sides))<2:return (h*1.5,-.35,-23)
 L=min(4.0,min(max(p[0] for p in s) for s in sides))
 L=max(1.8,L)
 y=sum(interp(s,L) for s in sides)/2
 corners=cam.get('target_corners',[])
 if len(corners)>=2:
  cp=[]
  for b,d in corners:
   a=math.radians(b+h);cp.append((-d*math.cos(a),d*math.sin(a)))
  far=max(p[0] for p in cp)
  edge=[p for p in cp if p[0]>far-.8]
  if len(edge)>=2:
   L=max(1.5,far);y=sum(p[1] for p in edge)/len(edge)
 desired=math.degrees(math.atan2(7.3*y,L*L))
 desired=max(-28,min(28,desired))
 steer=max(-32,min(32,2.25*h-1.5*desired))
 last=steer
 return (steer,-.65,-23)

